import{_ as a,o as i,c as n,a2 as o}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Panorama de magia","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/magic.md","filePath":"es/game-design/magic.md"}'),t={name:"es/game-design/magic.md"};function r(s,e,d,c,l,p){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="magic-redesign-v0-1" tabindex="-1">Panorama de magia <a class="header-anchor" href="#magic-redesign-v0-1" aria-label="Enlace permanente a &quot;Panorama de magia&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto. Ejemplos numéricos: solo objetivos de ajuste. Implementación: esta tarea cambia únicamente documentación; aquí no se establece implementación del rediseño mágico ni validación en ejecución.</strong></p><p>Registrado el 2026-10-04 como propuesta de gameplay. Esta es la sede canónica de la propuesta, no un plan aprobado de implementación ni un catálogo final de hechizos. Los fundamentos existentes en estado Aceptado —autoridad del servidor, <a href="/Syrolands-Public/es/game-design/combat/body-regions.html">Hits globales e integridad local</a> y <a href="/Syrolands-Public/es/game-design/combat/damage.html">Local Trauma separado</a>— siguen vigentes. Las nuevas mecánicas mágicas siguientes siguen en estado <strong>Propuesto</strong> salvo identificación explícita como fundamento heredado. Instituciones, hechizos, glifos y posturas con nombre son <strong>ejemplos ilustrativos</strong>, no contenido establecido del mundo.</p><h2 id="batch-04-reading-map" tabindex="-1">Mapa de lectura del Batch 04 <a class="header-anchor" href="#batch-04-reading-map" aria-label="Enlace permanente a &quot;Mapa de lectura del Batch 04&quot;">​</a></h2><p><strong>Revisado 2026-10-09:</strong> la fuente del Batch 04 amplía este ecosistema en estado Propuesto. No aprueba implementación ni sustituye fundamentos de combate aceptados. <a href="/Syrolands-Public/es/guide/magic/overview.html">Panorama para jugadores</a>.</p><table tabindex="0"><thead><tr><th>Referencia</th><th>Alcance</th></tr></thead><tbody><tr><td><a href="/Syrolands-Public/es/game-design/magic/spell-knowledge.html">Conocimiento de hechizos y Core Patterns</a></td><td>Identidad aprendida, descubrimiento y ejecución</td></tr><tr><td><a href="/Syrolands-Public/es/game-design/magic/variants-and-glyphs.html">Variantes y glifos</a></td><td>Modificadores acotados y compatibilidad</td></tr><tr><td><a href="/Syrolands-Public/es/game-design/magic/memory-and-familiarity.html">Familiarity y Active Memory</a></td><td>Práctica, preparación, INT y consulta bajo presión</td></tr><tr><td><a href="#meditation-and-concentration">Meditation y Concentration</a></td><td>Regulación mental y estabilidad de lanzamiento; sigue definida aquí</td></tr><tr><td><a href="/Syrolands-Public/es/game-design/magic/spellbooks-scrolls-and-reagents.html">Libros de hechizos, pergaminos y reactivos</a></td><td>Persistencia del conocimiento, recursos físicos y botín</td></tr><tr><td><a href="/Syrolands-Public/es/game-design/professions/inscription.html">Inscription</a></td><td>Ingeniería mágica y especialización profesional</td></tr><tr><td><a href="/Syrolands-Public/es/game-design/magic/presentation.html">Presentación mágica</a></td><td>Gramática visual modular y legibilidad mecánica</td></tr><tr><td><a href="/Syrolands-Public/es/game-design/magic/status-and-open-questions.html">Estado y preguntas abiertas</a></td><td>Conciliación entre batches y reglas sin decidir</td></tr></tbody></table><p>Instituciones, Difficulty de ejecución, Mastery más amplia, lanzamiento localizado, componentes de lanzamiento, tradiciones prohibidas y estados meditativos siguientes conservan sus propuestas anteriores. El Batch 04 no rediseña Necromancy, Voodoo, Chivalry ni todas las escuelas mágicas.</p><h2 id="identity-and-principles" tabindex="-1">Identidad y principios <a class="header-anchor" href="#identity-and-principles" aria-label="Enlace permanente a &quot;Identidad y principios&quot;">​</a></h2><p>Rediseñar el ecosistema mágico desde sus principios, conservando las ideas útiles de UO. Los hechizos originales son una biblioteca de ideas que pueden conservarse, reelaborarse, renombrarse, reubicarse o eliminarse; ningún hechizo heredado tiene un lugar garantizado automáticamente.</p><table tabindex="0"><thead><tr><th>Concepto</th><th>Función prevista</th></tr></thead><tbody><tr><td>Magery</td><td>Capacidad general de ejecución</td></tr><tr><td>Conocimiento de hechizos</td><td>Técnicas que el personaje ha aprendido permanentemente</td></tr><tr><td>Mastery / dominio</td><td>Profundidad de comprensión y especialización</td></tr><tr><td>Academias, órdenes y maestros</td><td>Dónde y cómo se adquiere conocimiento</td></tr><tr><td>Inscription</td><td>Ingeniería, codificación y modificación mágicas</td></tr><tr><td>Meditation</td><td>Regulación interna, concentración y estados mentales</td></tr></tbody></table><p>La propuesta conserva estos principios:</p><ol><li>La exploración amplía el vocabulario mágico; Magery alta no otorga automáticamente todos los hechizos.</li><li>La especialización mejora fiabilidad y profundidad, no solo daño.</li><li>La magia participa en el mismo modelo de combate localizado que el cuerpo a cuerpo.</li><li>El conocimiento prohibido tiene consecuencias sociales, geográficas y mecánicas.</li><li>Inscription sigue siendo una profesión artesanal y económica importante.</li><li>Meditation aporta decisiones activas de construcción del personaje más allá de recuperar maná.</li><li>Concentration genera presión de combate y posibilidades de respuesta.</li><li>Las academias son instituciones del mundo, no tiendas de libros completos de hechizos.</li><li>Los pergaminos consumibles proporcionan acceso temporal sin sustituir el aprendizaje permanente.</li><li>Los modificadores ofrecen contrapartidas tácticas horizontales en vez de mejoras obligatorias.</li><li>Preservar el espíritu sin clases de UO y los híbridos viables; no consumir todo el límite de habilidades en habilidades elementales separadas.</li><li>Hacer accesible la magia inicial útil sin macros tediosas, mientras la maestría profunda requiere exploración y experiencia a largo plazo.</li></ol><h2 id="knowledge-and-world-institutions" tabindex="-1">Conocimiento e instituciones del mundo <a class="header-anchor" href="#knowledge-and-world-institutions" aria-label="Enlace permanente a &quot;Conocimiento e instituciones del mundo&quot;">​</a></h2><h3 id="permanent-learning" tabindex="-1">Aprendizaje permanente <a class="header-anchor" href="#permanent-learning" aria-label="Enlace permanente a &quot;Aprendizaje permanente&quot;">​</a></h3><p>Un hechizo correctamente aprendido se convierte en conocimiento permanente del personaje. Un personaje con Magery 100 podría conocer pocos hechizos; otro podría conocer muchos pero carecer de capacidad de ejecución para lanzar los difíciles con fiabilidad. El conocimiento raro debería expresar la historia del personaje.</p><p>El conocimiento viene de viajes, academias, órdenes, cultos, maestros independientes u ocultos, grimorios, ruinas, jefes, cadenas de misiones, eventos del mundo y entidades sobrenaturales. Las academias formales no monopolizan todas las técnicas. Aprender un hechizo base no tiene por qué acabar la exploración: otro maestro podría ofrecer una fórmula rara o un método de ejecución para él.</p><h3 id="four-independent-dimensions" tabindex="-1">Cuatro dimensiones independientes <a class="header-anchor" href="#four-independent-dimensions" aria-label="Enlace permanente a &quot;Cuatro dimensiones independientes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dimensión</th><th>Significado</th><th>Candidatos ilustrativos, no taxonomía final</th></tr></thead><tbody><tr><td>Disciplina</td><td>Qué hace el mago</td><td>Destruction, Alteration, Conjuration / Invocation, Restoration, Illusion, Abjuration, Divination, Translocation, Necromancy, Voodoo</td></tr><tr><td>Afinidad / manifestación</td><td>Fenómeno, medio o expresión</td><td>Fire, Frost / Ice, Lightning, Poison, Shadow, Blood, Arcane, Earth, Wind</td></tr><tr><td>Técnica</td><td>Un hechizo aprendido</td><td>Wall of Fire, Incinerate, Napalm, Blink, Flame Ward, Heat Metal, Raise Corpse, Sense Magic</td></tr><tr><td>Tradición / institución</td><td>Quién lo enseña, con qué filosofía y restricciones</td><td>Academia, orden, culto, maestro independiente</td></tr></tbody></table><p>Un especialista en fuego no tiene por qué especializarse en Destruction. El fuego puede apoyar alteración, protección, conjuración y utilidad. No fusionar estas dimensiones en una Fire School genérica que contenga todos los hechizos de fuego.</p><p><strong>Ilustración:</strong> un Ashen Collegium cerca de un volcán podría enseñar fuego destructivo, manipulación térmica, protección contra fuego y conjuración de cenizas. Una academia militar podría compartir contenido de fuego enfatizando asedio, humo, señales, control del campo de batalla y denegación de áreas. El solapamiento parcial da motivos al especialista para viajar entre instituciones. Estos nombres no eligen ubicaciones reales del mapa ni crean facciones.</p><h3 id="admission-lessons-and-standing" tabindex="-1">Admisión, lecciones y posición <a class="header-anchor" href="#admission-lessons-and-standing" aria-label="Enlace permanente a &quot;Admisión, lecciones y posición&quot;">​</a></h3><p>Separar los requisitos para <strong>entrar</strong>, los requisitos para <strong>aprender una técnica concreta</strong> y las condiciones para <strong>mantener una buena posición</strong>. Los requisitos candidatos incluyen matrícula, umbrales de Magery, reputación, posición en facciones, misiones, derrota de un jefe, demostración técnica, objetos raros, alineamiento moral/criminal, admisión exclusiva de PK, pruebas regionales y afiliación previa a otra institución.</p><p>Los requisitos deberían expresar identidad: una academia comercial cobra matrícula; una orden territorial pide servicio regional; un círculo clandestino exige complicidad; un maestro de élite solicita técnica demostrada. Perder el favor debería normalmente restringir enseñanzas futuras, servicios, rangos o instalaciones en vez de borrar conocimiento aprendido. Son posibles afiliaciones parcialmente incompatibles, pero siguen sin resolverse.</p><h2 id="magery-execution-and-progression" tabindex="-1">Magery: ejecución y progresión <a class="header-anchor" href="#magery-execution-and-progression" aria-label="Enlace permanente a &quot;Magery: ejecución y progresión&quot;">​</a></h2><h3 id="attempt-floor-versus-execution-difficulty" tabindex="-1">Umbral de intento frente a Difficulty de ejecución <a class="header-anchor" href="#attempt-floor-versus-execution-difficulty" aria-label="Enlace permanente a &quot;Umbral de intento frente a Difficulty de ejecución&quot;">​</a></h3><p>Cada hechizo debería distinguir <strong>Minimum Magery</strong>, el mínimo para intentarlo, de <strong>Difficulty</strong>, el desafío de ejecutarlo con éxito. Cumplir requisitos no equivale a competencia. Se prefiere una curva de fiabilidad no lineal; no se adopta ecuación ni porcentaje.</p><p><strong>Solo ilustraciones numéricas:</strong> Minimum Magery 50 podría permitir fallos frecuentes a 50 y mayor fiabilidad por encima. Minimum Magery 100 podría describir todavía un hechizo que falle significativamente con habilidad 100 cuando Difficulty esté cerca o más allá del límite. Resurrección mayor, teletransporte a gran escala, invocaciones peligrosas, rituales de batalla o magia prohibida son ejemplos de hechizos más allá del dominio generalista fiable, no capacidades definitivas.</p><p>La dirección de ajuste es poca fiabilidad en el extremo inferior apto, competencia en la zona media y fiabilidad con habilidad alta, con hechizos extremos aún falibles. Costes y modificadores siguen sin resolverse.</p><h3 id="use-based-gain-and-structured-teaching" tabindex="-1">Progreso por uso y enseñanza estructurada <a class="header-anchor" href="#use-based-gain-and-structured-teaching" aria-label="Enlace permanente a &quot;Progreso por uso y enseñanza estructurada&quot;">​</a></h3><p>Los intentos de lanzamiento deberían poder mejorar Magery. El desafío relativo importa: hechizos cercanos a la capacidad proporcionan oportunidades de aprender; los triviales dejan de entrenar habilidad muy alta, y una dificultad totalmente inadecuada también puede ser ineficiente. La curva exacta de progreso y si/cómo contribuyen los intentos fallidos no son definitivos.</p><p>Las academias también ofrecen progresión significativa mediante ejercicios, exámenes, misiones, materiales, pagos y demostraciones. <strong>Aproximadamente +5 de habilidad por bloque de entrenamiento</strong> y <strong>alrededor de Magery 55–60 durante un primer día dedicado</strong> son objetivos ilustrativos de progresión/ritmo, no garantías, valores de configuración ni balance fijado.</p><p>La competencia inicial debería ser accesible; la zona media combina enseñanza y práctica; la habilidad mayor necesita uso difícil, maestros especializados, entrenamiento raro y experiencia. Los NPC no deberían entrenar trivialmente a un personaje hasta 100. Esta propuesta no cambia la <a href="/Syrolands-Public/es/game-design/skills-and-knowledge.html">base actual de límite de habilidades/progresión</a>.</p><h3 id="fizzle-versus-interruption" tabindex="-1">Fizzle frente a interrupción <a class="header-anchor" href="#fizzle-versus-interruption" aria-label="Enlace permanente a &quot;Fizzle frente a interrupción&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Concepto</th><th>Significado</th><th>Influencias en estado Propuesto</th></tr></thead><tbody><tr><td>Fizzle</td><td>Fallo al ejecutar correctamente la estructura mágica</td><td>Magery frente a Difficulty efectiva y modificadores pertinentes</td></tr><tr><td>Interrupción</td><td>La presión de combate perturba un lanzamiento que el mago podría ejecutar de otro modo</td><td>Daño, movimiento, trauma local, pérdida de concentración, cambios de estado o efectos incapacitantes</td></tr></tbody></table><p>Mantenerlos mecánicamente distintos. No inferir costes de reactivos, maná, enfriamiento o recuperación para ninguno de los resultados hasta especificarlos.</p><h2 id="mastery-without-rigid-classes" tabindex="-1">Mastery sin clases rígidas <a class="header-anchor" href="#mastery-without-rigid-classes" aria-label="Enlace permanente a &quot;Mastery sin clases rígidas&quot;">​</a></h2><p>No convertir automáticamente disciplinas o afinidades en ocho o diez habilidades separadas de 0–100. Mastery puede existir fuera del sistema clásico de límite de habilidades; su representación y límites siguen abiertos. Preservar híbridos viables y generalistas significativos.</p><p>La propuesta principal es <strong>reducir la Difficulty efectiva de hechizos avanzados pertinentes</strong>, con poca ventaja para los básicos y mayor utilidad del especialista para técnicas difíciles o extremas. Un especialista en fuego podría ejecutar Incinerate con más fiabilidad que un generalista de igual habilidad. Mastery no es un multiplicador fijo de daño.</p><p>Otras ventajas candidatas incluyen menor repercusión adversa, colocación de áreas más fina, selección avanzada de objetivos, mejor información, modos especiales de ejecución y ventajas específicas del campo. Novice, Adept, Scholar y Master son posibles niveles cualitativos, no rangos definitivos.</p><p>La progresión puede considerar técnicas conocidas, rareza, variedad, maestros, instituciones visitadas, misiones, uso práctico y modificadores avanzados. Evitar una lista comprable de cantidad de hechizos o una ruta fija de compras de una wiki. No se aprueba recuento, peso, umbral de desbloqueo ni regla de incompatibilidad.</p><h2 id="spellbooks-scrolls-and-inscription" tabindex="-1">Libros de hechizos, pergaminos e Inscription <a class="header-anchor" href="#spellbooks-scrolls-and-inscription" aria-label="Enlace permanente a &quot;Libros de hechizos, pergaminos e Inscription&quot;">​</a></h2><p>El Batch 04 separa a continuación las referencias detalladas. El material anterior se conserva allí; estos encabezados preservan enlaces entrantes existentes. Todas las nuevas mecánicas siguen en estado Propuesto.</p><h3 id="knowledge-belongs-to-the-character" tabindex="-1">El conocimiento pertenece al personaje <a class="header-anchor" href="#knowledge-belongs-to-the-character" aria-label="Enlace permanente a &quot;El conocimiento pertenece al personaje&quot;">​</a></h3><p>El conocimiento permanente sigue siendo distinto del libro físico y su valor como botín. <a href="/Syrolands-Public/es/game-design/magic/spellbooks-scrolls-and-reagents.html#knowledge-belongs-to-the-character">Especificación detallada</a>.</p><h3 id="scrolls-provide-temporary-access" tabindex="-1">Los pergaminos proporcionan acceso temporal <a class="header-anchor" href="#scrolls-provide-temporary-access" aria-label="Enlace permanente a &quot;Los pergaminos proporcionan acceso temporal&quot;">​</a></h3><p>Los pergaminos ordinarios de lanzamiento proporcionan ejecución temporal, no aprendizaje permanente automático. <a href="/Syrolands-Public/es/game-design/magic/spellbooks-scrolls-and-reagents.html#scrolls-provide-temporary-access">Especificación detallada</a>.</p><h3 id="inscription-as-magical-engineering" tabindex="-1">Inscription como ingeniería mágica <a class="header-anchor" href="#inscription-as-magical-engineering" aria-label="Enlace permanente a &quot;Inscription como ingeniería mágica&quot;">​</a></h3><p>Inscription define codificación, conservación y transformación controlada de estructuras aprendidas. <a href="/Syrolands-Public/es/game-design/professions/inscription.html#inscription-as-magical-engineering">Especificación detallada</a>.</p><h3 id="horizontal-spell-augmentation" tabindex="-1">Ampliación horizontal de hechizos <a class="header-anchor" href="#horizontal-spell-augmentation" aria-label="Enlace permanente a &quot;Ampliación horizontal de hechizos&quot;">​</a></h3><p>Los modificadores aprendidos ofrecen contrapartidas tácticas acotadas, no acumulación gratuita de mejoras. <a href="/Syrolands-Public/es/game-design/magic/variants-and-glyphs.html#horizontal-spell-augmentation">Especificación detallada</a>.</p><h3 id="prepared-configurations-and-crafted-grimoires" tabindex="-1">Configuraciones preparadas y grimorios elaborados <a class="header-anchor" href="#prepared-configurations-and-crafted-grimoires" aria-label="Enlace permanente a &quot;Configuraciones preparadas y grimorios elaborados&quot;">​</a></h3><p>Variantes preparadas, conocimiento permanente y ventajas físicas de grimorios son conceptos distintos. <a href="/Syrolands-Public/es/game-design/magic/variants-and-glyphs.html#prepared-configurations-and-crafted-grimoires">Especificación detallada</a>.</p><h2 id="localized-magic-and-injury" tabindex="-1">Magia localizada y lesiones <a class="header-anchor" href="#localized-magic-and-injury" aria-label="Enlace permanente a &quot;Magia localizada y lesiones&quot;">​</a></h2><p>La magia debe participar en el mismo modelo anatómico que las armas; cada hechizo necesita un perfil de impacto/daño/trauma apropiado a su forma en vez de solo una cifra genérica de HP. Conservar <a href="/Syrolands-Public/es/game-design/combat/damage.html">daño global frente a Local Trauma</a>, <a href="/Syrolands-Public/es/game-design/combat/body-regions.html">regiones independientes</a> y resultados resueltos por el servidor.</p><table tabindex="0"><thead><tr><th>Forma ilustrativa</th><th>Interacción candidata, no regla implementada</th></tr></thead><tbody><tr><td>Proyectil</td><td>Ubicación anatómica específica seleccionada por perfil de impacto/selección de objetivo</td></tr><tr><td>Explosión</td><td>Trauma distribuido sobre varias regiones</td></tr><tr><td>Área sobre el suelo</td><td>Exposición desproporcionada de piernas/pies; los pies no son nuevas regiones corporales independientes aprobadas</td></tr><tr><td>Maldición</td><td>Deterioro de una extremidad específica</td></tr><tr><td>Térmica</td><td>Quemaduras, daño tisular o armadura calentada</td></tr><tr><td>Escarcha</td><td>Rigidez, movilidad reducida, fragilidad o congelación local</td></tr><tr><td>Rayo</td><td>Espasmos, pérdida temporal de control o penalizaciones de precisión</td></tr><tr><td>Cinética / fuerza</td><td>Trauma contundente, fracturas o empuje</td></tr><tr><td>Ácido / corrosión</td><td>Desgaste de armadura y daño tisular</td></tr><tr><td>Nigromántica / sobrenatural</td><td>Efectos de vitalidad que no necesitan comportarse como trauma contundente/de corte</td></tr></tbody></table><p>No aplicar automáticamente el adaptador de armadura cuerpo a cuerpo heredado, trauma residual ×2, regla de región primaria única ni requisito actual de pérdida de HP a toda forma mágica. Exposición, armadura/resistencia, presupuestos multirregión, contactos repetidos de área y maldiciones sin daño necesitan contratos explícitos propios. La parte cuerpo a cuerpo conserva su alcance; esta propuesta no implementa propagación ni altera sus pruebas.</p><h3 id="normal-and-focused-cast" tabindex="-1">Normal Cast y Focused Cast <a class="header-anchor" href="#normal-and-focused-cast" aria-label="Enlace permanente a &quot;Normal Cast y Focused Cast&quot;">​</a></h3><p><strong>Propuesto:</strong> Normal Cast usa el perfil anatómico natural del hechizo. Focused Cast intenta una extremidad conocida, requiere suficiente información/Anatomy y añade Difficulty de ejecución, tiempo, recursos u otro coste significativo. La selección sigue siendo intención, no impacto/ubicación garantizados. La interacción exacta con <a href="/Syrolands-Public/es/game-design/combat/targeting.html">selección de objetivos</a> sigue sin resolverse; no copiar al lanzamiento su probabilidad experimental de 50% cuerpo a cuerpo.</p><p><strong>Ilustración:</strong> un mago informado apunta Ice Lance a la pierna izquierda anatómica del objetivo y acepta mayor dificultad de ejecución. La Mastery pertinente podría compensar parte de esa dificultad adicional. Flash Freeze podría aprovechar una pierna Wounded, Combust Wound el tejido dañado, o una maldición dirigida un brazo ya débil. Son interacciones propuestas que apoyan la lectura táctica, no una rotación de DPS ni multiplicadores aprobados de heridas.</p><p>La <a href="/Syrolands-Public/es/game-design/skills-and-knowledge.html">información de Anatomy</a> experimental actual no es automáticamente el prerrequisito final de selección de objetivos mágicos. Determinar conocimiento requerido, vigencia y visibilidad antes de diseñar su contrato.</p><h3 id="casting-components-and-injured-limbs" tabindex="-1">Componentes de lanzamiento y extremidades lesionadas <a class="header-anchor" href="#casting-components-and-injured-limbs" aria-label="Enlace permanente a &quot;Componentes de lanzamiento y extremidades lesionadas&quot;">​</a></h3><p>Las etiquetas candidatas de componentes incluyen Verbal, Gestural, Focused y Ritual; los hechizos no necesitan depender de los mismos componentes. Un trauma grave en la cabeza podría desestabilizar concentración/Meditation; una lesión de brazo podría penalizar gestos; trauma torácico podría afectar respiración, resistencia, canalizaciones largas o rituales. Las etiquetas podrían interactuar con silencio e inmovilización.</p><p>One-Handed Casting y Silent Casting son ejemplos de técnicas raras aprendidas, no ventajas genéricas automáticas. Umbrales exactos, alternativas y reglas de componentes siguen sin resolverse. Estas penalizaciones propuestas <strong>no</strong> sustituyen las <a href="/Syrolands-Public/es/game-design/combat/disability.html">reglas limitadas de incapacidad de Slice 0</a> ni autorizan penalizaciones funcionales adicionales en la implementación cuerpo a cuerpo actual.</p><h2 id="meditation-and-concentration" tabindex="-1">Meditation y Concentration <a class="header-anchor" href="#meditation-and-concentration" aria-label="Enlace permanente a &quot;Meditation y Concentration&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/magic/meditation-and-concentration.html">Guía del jugador</a>. Esta sección sigue siendo la única referencia de regulación mental y estabilidad de lanzamiento; <a href="/Syrolands-Public/es/game-design/magic/memory-and-familiarity.html">Active Memory</a> define capacidad del repertorio y reglas de consulta.</p><p><strong>Batch 04, Propuesto:</strong> Meditation puede organizar y reorganizar Active Memory, preparar patrones difíciles y recuperar la disposición mental. Una Meditation mayor puede hacer más rápidos/seguros los cambios de repertorio y más fuerte la recuperación de Concentration; no se otorga fórmula, cambio instantáneo en combate ni preparación gratuita. Daño, movimiento, trauma local, efectos contundentes/aturdimiento, presión repetida, fatiga, rasgos de objetos y variantes difíciles son candidatos de presión, no penalizaciones recién implementadas. Preservar la distinción siguiente entre fizzle de ejecución e interrupción; Concentration no es automáticamente otra habilidad con límite.</p><p>Meditation es control mental y regulación mágica interna además de recuperación de maná. La habilidad representa capacidad; las técnicas meditativas específicas representan conocimiento. Las técnicas avanzadas pueden enseñarse en monasterios, órdenes militares, academias, cultos o por maestros ocultos, con reglas precisas de adquisición/desbloqueo aún abiertas. Los estados no son hechizos ordinarios y deberían ser compromisos con contrapartidas, no bonificaciones gratuitas activables.</p><table tabindex="0"><thead><tr><th>Estado ilustrativo</th><th>Ventaja posible</th><th>Compromiso/coste posible</th></tr></thead><tbody><tr><td>Trance of Stillness</td><td>Recuperación fuerte de maná, concentración estable, menor Difficulty</td><td>Inmovilidad/penalización grave de movimiento, percepción reducida, demora de salida</td></tr><tr><td>Battle Meditation</td><td>Recuperación moderada bajo presión de combate, resistencia a interrupción</td><td>Penalización de Stamina, movilidad reducida u otra contrapartida</td></tr><tr><td>Empty Mind</td><td>Resistencia a Illusion, Fear, Charm o Voodoo mental</td><td>Divination ofensiva o mantenimiento de invocaciones más débiles</td></tr><tr><td>Flow State</td><td>Uso coherente más estable de disciplina/afinidad</td><td>Cambiar de campo rompe el estado</td></tr><tr><td>Deep Channel</td><td>Acceso a intentos extremadamente difíciles</td><td>Mayor uso de maná y vulnerabilidad</td></tr><tr><td>Ember Trance</td><td>Estabilidad del especialista en fuego y menor Difficulty efectiva</td><td>Otras afinidades pueden hacerse más difíciles</td></tr></tbody></table><p>Ember Trance ilustra interacción entre Fire Mastery y Meditation fuerte, no una postura ni requisito definitivos.</p><h3 id="concentration-under-pressure" tabindex="-1">Concentration bajo presión <a class="header-anchor" href="#concentration-under-pressure" aria-label="Enlace permanente a &quot;Concentration bajo presión&quot;">​</a></h3><p>Concentration es una capa jugable adicional propuesta, no necesariamente otra habilidad visible de 0–100. Podría ser recurso dinámico, estado interno o medidor parcialmente visible; representación e interfaz siguen sin resolverse.</p><p>Las influencias candidatas incluyen golpes, movimiento, trauma local, cambios de objetivo, mantenimiento de invocaciones, efectos mentales, lanzamientos complejos e interrupciones. Meditation puede restaurarla, estabilizarla o conservarla. El lanzamiento avanzado puede requerir suficiente Mana, Magery <strong>y</strong> Concentration. El maná restante por sí solo no debería hacer que un mago presionado actúe igual que uno sin molestias; el cuerpo a cuerpo puede perturbar el control antes de agotar la salud. Recuperación, deterioro, umbrales y fórmulas de interrupción no están elegidos.</p><h2 id="forbidden-traditions" tabindex="-1">Tradiciones prohibidas <a class="header-anchor" href="#forbidden-traditions" aria-label="Enlace permanente a &quot;Tradiciones prohibidas&quot;">​</a></h2><h3 id="necromancy" tabindex="-1">Necromancy <a class="header-anchor" href="#necromancy" aria-label="Enlace permanente a &quot;Necromancy&quot;">​</a></h3><p>Estado Propuesto de la identidad: muerte, cadáveres, almas, reanimación, transferencia de vitalidad y estados post mortem. El conocimiento podría encontrarse en criptas, cultos, maestros ocultos, grimorios prohibidos, ruinas y entidades no muertas, en vez de un catálogo normal de academia pública. Aprender puede afectar relaciones institucionales/con facciones. No introducir “puntos de maldad” genéricos sin una decisión más amplia de diseño del mundo.</p><h3 id="voodoo-sympathetic-magic-and-personal-links" tabindex="-1">Voodoo: magia simpática y vínculos personales <a class="header-anchor" href="#voodoo-sympathetic-magic-and-personal-links" aria-label="Enlace permanente a &quot;Voodoo: magia simpática y vínculos personales&quot;">​</a></h3><p>Voodoo tiene una identidad propuesta distinta: usar materiales/restos personales para establecer una conexión con un personaje concreto. No es sinónimo de Necromancy.</p><p><strong>Ciclo ilustrativo:</strong> matar o descubrir el cadáver de otro jugador → obtener un resto personal (cabeza, sangre, pelo, hueso) mediante una interacción permitida → realizar un ritual en un altar → crear una Voodoo Effigy vinculada al personaje → usar efectos bajo condiciones definidas. Anatomy, Forensics, conocimiento de Voodoo, Carpentry y otras habilidades artesanales son posibles participantes, no requisitos asignados. Propiedad, requisitos de extracción y recetas del altar siguen sin resolverse.</p><table tabindex="0"><thead><tr><th>Efecto ilustrativo</th><th>Propósito posible</th></tr></thead><tbody><tr><td>Needle of Agony</td><td>Daño remoto/semirremoto</td></tr><tr><td>Withering Curse</td><td>Reducción temporal de atributos o regeneración</td></tr><tr><td>Limping Hex</td><td>Deterioro de una pierna específica</td></tr><tr><td>Silence of the Tongue</td><td>Perturbación del lanzamiento</td></tr><tr><td>Marked Blood</td><td>Rastreo direccional</td></tr><tr><td>Dream Fever</td><td>Debilitamiento gradual</td></tr><tr><td>Binding Thread</td><td>Interferencia con Recall/Gate/Translocation</td></tr><tr><td>Shared Pain</td><td>Una forma de daño recibido vinculado</td></tr><tr><td>Effigy Rupture</td><td>Efecto potente de un uso que consume la efigie</td></tr></tbody></table><p><strong>La propuesta exige formas de contrarrestarlo:</strong> una muerte no debe permitir hostigamiento permanente ilimitado. Las restricciones candidatas incluyen deterioro de vínculos/potencia de restos, proximidad para los efectos más fuertes, consumo material, cantidad limitada de vínculos mantenidos, detección/identificación por Divination, purificación para cortar vínculos y protecciones defensivas. Duraciones exactas, alcance, costes, límites y protección de víctimas siguen sin resolverse; los ejemplos no otorgan capacidad irrestricta de PvP remoto.</p><p>La fantasía prevista —“ese enemigo posee una parte de mí”— conecta PvP, cadáveres, Anatomy/Forensics, vivienda, Carpentry, artesanía ritual, Inscription, Divination y contramagia. Sigue necesitando una política coherente contra el hostigamiento antes de implementarse.</p><h2 id="illustrative-character-identity" tabindex="-1">Identidad ilustrativa de personaje <a class="header-anchor" href="#illustrative-character-identity" aria-label="Enlace permanente a &quot;Identidad ilustrativa de personaje&quot;">​</a></h2><p>Todos los números e interacciones aquí son ilustrativos, no requisitos de configuración del personaje ni balance probado.</p><table tabindex="0"><thead><tr><th>Personaje A</th><th>Personaje B</th></tr></thead><tbody><tr><td>Magery 92, Meditation 85, Anatomy 70</td><td>Magery 100, Meditation 30, Anatomy 0</td></tr><tr><td>Fire Mastery alta; Incinerate y un modificador avanzado de fuego aprendidos</td><td>Sin Fire Mastery</td></tr><tr><td>Podría sostener un estado de fuego, inspeccionar una pierna lesionada e intentar un Incinerate enfocado más difícil, compensado en parte por Mastery</td><td>Una ejecución general más fuerte no confiere automáticamente la selección anatómica, fiabilidad de fuego o control de concentración de A</td></tr></tbody></table><p>A sigue vulnerable a interrupción por pérdida de Concentration. El conocimiento real de hechizos de B no está especificado, no se infiere de Magery 100. El ejemplo muestra identidades de juego distintas sin clases rígidas ni afirmar que alguna configuración sea universalmente más fuerte.</p><h2 id="open-questions" tabindex="-1">Preguntas abiertas <a class="header-anchor" href="#open-questions" aria-label="Enlace permanente a &quot;Preguntas abiertas&quot;">​</a></h2><p>Todas las entradas siguen <strong>Sin resolver</strong>; esta lista no es un calendario aprobado de entrega.</p><table tabindex="0"><thead><tr><th>Área</th><th>Decisiones aún necesarias</th></tr></thead><tbody><tr><td>Ejecución</td><td>Fórmula exacta de éxito no lineal; Minimum Magery frente a Difficulty; costes de fizzle; consumo total/parcial/nulo de reactivos al fallar; distinción de costes de interrupción</td></tr><tr><td>Progresión</td><td>Fórmula de progreso de habilidad, límites de desafío y progreso por intentos fallidos; ritmo inicial; incrementos/límites de enseñanza</td></tr><tr><td>Mastery</td><td>Forma numérica/por niveles/oculta/visible/híbrida, relación con límite de habilidades, pesos de progresión y ventajas; límites de especialización</td></tr><tr><td>Taxonomía e instituciones</td><td>Disciplinas/afinidades finales, afiliaciones parcialmente excluyentes y reglas para conservar posición; qué hechizos originales de UO sobreviven</td></tr><tr><td>Libros y pergaminos</td><td>Protección/sustitución específica del libro personal frente al botín; restricciones exactas de pergaminos; qué hechizos prohibidos admiten pergaminos; requisitos de conocimiento/recetas del escriba</td></tr><tr><td>Ampliación</td><td>Número de espacios, configuración preparada frente a siempre disponible, reglas de cambio/consumo y políticas distintas de pérdida de libros elaborados</td></tr><tr><td>Concentration</td><td>Representación, recuperación/deterioro, interacción con movimiento, presión de invocaciones/cambios de objetivo y fórmulas de interrupción</td></tr><tr><td>Lanzamiento localizado</td><td>Perfiles de impacto/trauma por hechizo, interacción armadura/resistencia, distribución multirregión, penalizaciones de enfoque y función exacta de Anatomy al seleccionar objetivo</td></tr><tr><td>Componentes</td><td>Etiquetas verbal/gestual/enfocado/ritual, interacciones con lesión/silencio/inmovilización, reglas de lanzamiento con una mano/silencioso</td></tr><tr><td>Voodoo</td><td>Duración/alcance/condiciones de vínculos y respuestas; extracción de restos de cadáveres; protecciones contra hostigamiento; función de Forensics; requisitos artesanales de altares</td></tr><tr><td>Meditation</td><td>Desbloqueos aprendidos/descubiertos/por umbral de habilidad; restricciones, costes y contrapartidas exactos; interacción Mastery/estado</td></tr><tr><td>Presentación</td><td>Obtención de recursos, compatibilidad del renderizador, visibilidad/información revelada y futuro contrato de efectos; sin proceso de producción elegido</td></tr></tbody></table><h2 id="proposed-environmental-interaction" tabindex="-1">Interacción ambiental en estado Propuesto <a class="header-anchor" href="#proposed-environmental-interaction" aria-label="Enlace permanente a &quot;Interacción ambiental en estado Propuesto&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/living-world.html#magic-and-tactical-preparation">Mundo vivo y materiales</a> propone respuestas materiales compartidas al calor, agua, frío, rayos, viento y efectos de tierra. Fireball aporta estímulos genéricos de calor/ignición en vez de scripts de quemado específicos por objeto. Efectos ambientales de hechizos, integración meteorológica y cambios tácticos del terreno siguen en estado Propuesto; el prototipo candidato de árboles/hierba no es autorización de implementación ni lista final de hechizos.</p><h2 id="integration-boundary-and-sources" tabindex="-1">Límite de integración y fuentes <a class="header-anchor" href="#integration-boundary-and-sources" aria-label="Enlace permanente a &quot;Límite de integración y fuentes&quot;">​</a></h2><p><strong>Autoridad:</strong> la intención del cliente podría solicitar un lanzamiento enfocado; ModernUO debe resolver requisitos, objetivos, casillas afectadas, duración, daño, trauma, estado y efectos de colisión/área. Los datos sincronizados contendrían solo información aprobada por el servidor; ClassicUO presentaría efectos/indicaciones. Ninguna animación del cliente ni colisión de partículas puede decidir gameplay.</p><p>Las ambiciones visuales son una cuestión técnica separada; los efectos estándar de UO no deben definir el diseño de hechizos. Aquí no se ha asignado identificador de efecto, paquete, esquema de persistencia ni renderizador.</p><p><strong>Implementación actual y brecha:</strong> la documentación existente registra combate cuerpo a cuerpo localizado natural y Anatomy experimental en la parte actual. No establece que este ecosistema mágico esté implementado. Ni la integración original ni el Batch 04 establecen una auditoría nueva del código heredado de hechizos ni cambian su comportamiento. Véanse los límites de evidencia de herencia. Aprendizaje permanente, instituciones, mastery, cambios de pergaminos/Inscription, concentración y lanzamiento localizado necesitan futuros diseños técnicos aprobados, implementaciones acotadas y pruebas de juego. La magia nueva sigue fuera de la parte actual; esta propuesta no sustituye ningún ADR aceptado.</p><p><strong>Procedencia:</strong> Magic Redesign Documentation Prompt v0.1 aportado por el usuario, secciones 1–25, integrado el 2026-10-04. Las secciones fuente 1–3 corresponden a conocimiento/instituciones; 4–7 a ejecución/progresión/mastery; 8–13 a libros/pergaminos/Inscription; 14–15 y 18 a lanzamiento localizado; 16–17 y 21 a Meditation/Concentration; 19–20 a tradiciones prohibidas; 22–24 a identidad/principios/preguntas abiertas; 25 a la cuestión separada del renderizador. Las fuentes históricas de combate siguen intactas.</p><h2 id="profession-and-item-quality-proposals" tabindex="-1">Propuestas de profesiones y calidad de objetos <a class="header-anchor" href="#profession-and-item-quality-proposals" aria-label="Enlace permanente a &quot;Propuestas de profesiones y calidad de objetos&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/professions/alchemy.html">Alchemy</a> y <a href="/Syrolands-Public/es/game-design/professions/cooking.html">Cooking</a> proponen preparados/comida que pueden interactuar con recuperación o Concentration; <a href="/Syrolands-Public/es/game-design/professions/tinkering.html">Tinkering</a> deja la vinculación de constructos mágicos como posibilidad futura. <a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html">Rasgos de objetos y resonancia latente</a> necesitan compatibilidad y respuestas posibles en vez de efectos mágicos implícitos.</p><p>El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">registro de conciliación de profesiones</a> mantiene la dirección global de enseñanza/progreso separada de los bloques ilustrativos de entrenamiento de Magery y Difficulty de ejecución. El Batch 01 no acepta ritmo numérico, nueva habilidad Concentration, regla de Inscription ni excepción de pérdida del libro.</p><h2 id="batch-02-progression-and-int-reconciliation" tabindex="-1">Conciliación de progresión e INT del Batch 02 <a class="header-anchor" href="#batch-02-progression-and-int-reconciliation" aria-label="Enlace permanente a &quot;Conciliación de progresión e INT del Batch 02&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html#reconciliation-and-open-questions">Habilidades y límite de habilidades</a> centraliza el marco general de progreso/límite/maestros en estado Propuesto, incluida la franja 80–90 Muy lenta. Los bloques de +5 y ejemplos de 55–60 el primer día anteriores siguen siendo ilustraciones específicas de magia, no tasas generales. El trabajo rutinario fiable con poca habilidad y Difficulty falible de hechizos avanzados necesitan conciliación deliberada; este añadido no cambia el modelo de hechizos ni su texto existente.</p><p>La <a href="/Syrolands-Public/es/game-design/characters/stats.html#int-broader-mental-capability">dirección de INT</a> propone cognición, resiliencia mental y capacidad de recursos mágicos más allá del tamaño del maná. Su relación con Meditation, Concentration, conocimiento de hechizos y estados mentales sigue Sin resolver; no implica sistema completo de INT ni habilidad nueva.</p><h2 id="batch-03-combat-pressure-boundary" tabindex="-1">Límite de presión de combate del Batch 03 <a class="header-anchor" href="#batch-03-combat-pressure-boundary" aria-label="Enlace permanente a &quot;Límite de presión de combate del Batch 03&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/stamina-and-reactive-combat.html#concentration-pressure">Stamina y combate reactivo</a> vincula daño, trauma local, movimiento, presión repetida, aturdimiento/impacto y rasgos candidatos de armas al diseño existente de Concentration en estado Propuesto. Esto no elige fórmulas de interrupción, crea mecánicas de aturdimiento, redefine fizzle ni requiere una habilidad Concentration independiente. Magia sigue siendo la referencia canónica de estas distinciones.</p><h2 id="batch-04-provenance-and-progression" tabindex="-1">Procedencia y progresión del Batch 04 <a class="header-anchor" href="#batch-04-provenance-and-progression" aria-label="Enlace permanente a &quot;Procedencia y progresión del Batch 04&quot;">​</a></h2><p>El Batch 04 (A–X) añade Core Patterns, glifos acotados, Familiarity por patrón, Active Memory, espacio cognitivo de INT, riesgo material, Inscription y visuales modulares. El <a href="/Syrolands-Public/es/game-design/magic/status-and-open-questions.html">registro de conciliación</a> registra cambios de énfasis y conflictos sin resolver. Familiarity no consume límite de habilidades y es distinta de Mastery más amplia por disciplina/afinidad. Bajo la <a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html">dirección sin 120 ordinario en estado Propuesto</a>, Magery 100 es dominio técnico, no haber completado la magia: patrones raros, escuelas, modificadores, práctica, preparación, grimorios, rituales, conocimiento regional, reactivos raros, ejecución del jugador e Inscription sostienen la progresión a largo plazo. No se cambia límite ordinario de habilidades ni disponibilidad de hechizos.</p>',105)])])}const g=a(t,[["render",r]]);export{u as __pageData,g as default};
